// STEP 6 selector input normalization.
// Update READY_STATUS_IDS / DEAD_STATUS_IDS here if your Perfex status map changes.

const READY_STATUS_IDS = new Set(['3']);
const DEAD_STATUS_IDS = new Set(['6', '9']);
const DEAD_STATUS_KEYWORDS = [
  'dead',
  'discard',
  'bortsort',
  'invalid',
  'duplicate',
  'spam',
  'no email',
  'no-email',
  'ingen email',
  'utan email',
  'closed lost',
  'lost'
];
const CONTACTED_STATUS_KEYWORDS = [
  'contacted',
  'kontaktad',
  'replied',
  'reply',
  'customer',
  'kund',
  'converted',
  'meeting',
  'booked',
  'proposal',
  'offert',
  'won'
];

function clean(value) {
  return (value ?? '').toString().trim();
}

function lower(value) {
  return clean(value).toLowerCase();
}

function firstNonEmpty(...values) {
  for (const value of values) {
    const normalized = clean(value);
    if (normalized) {
      return normalized;
    }
  }
  return '';
}

function isTruthyish(value) {
  const normalized = lower(value);
  return normalized === '1' || normalized === 'true' || normalized === 'yes' || normalized === 'ja';
}

function looksLikePersonName(value) {
  const normalized = clean(value);
  if (!normalized) return false;

  const words = normalized.split(/\s+/).filter(Boolean);
  if (words.length < 2 || words.length > 4) return false;

  const haystack = lower(normalized);
  const companyHints = [
    'ab',
    'hb',
    'kb',
    'oy',
    'ltd',
    'llc',
    'gmbh',
    'agency',
    'byra',
    'marketing',
    'media',
    'shop',
    'store',
    'solutions',
    'group',
    'consult',
    'bygg',
    'elektriker',
    'vvs',
    'stadning',
    'transport',
    'service',
    'clinic',
    'klinik'
  ];

  if (companyHints.some((hint) => haystack.includes(hint))) {
    return false;
  }

  return words.every((word) => /^[\p{L}'.-]+$/u.test(word));
}

function extractIndustry(lead) {
  const direct = firstNonEmpty(
    lead.industry,
    lead.Industry,
    lead.branch,
    lead.Branch,
    lead.BranchName
  );
  if (direct) return direct;

  const groups = [lead.custom_fields, lead.customFields, lead.custom_fields_values, lead.custom_fields_value];

  for (const group of groups) {
    const extracted = extractIndustryFromGroup(group);
    if (extracted) return extracted;
  }

  return '';
}

function extractIndustryFromGroup(group) {
  if (!group) return '';

  if (Array.isArray(group)) {
    for (const entry of group) {
      const name = lower(entry?.name || entry?.label || entry?.field_name || entry?.title);
      const value = clean(entry?.value || entry?.field_value || entry?.fieldValue || entry?.answer);
      const fieldId = clean(entry?.id || entry?.fieldid || entry?.field_id);
      if (!value) continue;
      if (name.includes('industry') || name.includes('branch') || name.includes('bransch') || fieldId === '1') {
        return value;
      }
    }
    return '';
  }

  if (typeof group === 'object') {
    const direct = firstNonEmpty(group.industry, group.Industry, group.branch, group.Branch, group.bransch, group.Bransch, group['1']);
    if (direct) return direct;

    if (group.leads && typeof group.leads === 'object') {
      const nested = firstNonEmpty(
        group.leads.industry,
        group.leads.Industry,
        group.leads.branch,
        group.leads.Branch,
        group.leads.bransch,
        group.leads.Bransch,
        group.leads['1']
      );
      if (nested) return nested;
    }

    for (const [key, value] of Object.entries(group)) {
      if (typeof value === 'object' && value !== null) {
        const nested = extractIndustryFromGroup(value);
        if (nested) return nested;
      }
      if (['industry', 'branch', 'bransch', '1'].includes(lower(key)) && clean(value)) {
        return clean(value);
      }
    }
  }

  return '';
}

function hasContactEvidence(lead) {
  const rawFields = [
    lead.lastcontact,
    lead.last_contact,
    lead.datecontacted,
    lead.date_contacted,
    lead.contacted_at,
    lead.last_email_sent_at,
    lead.email_last_sent_at,
    lead.first_outreach_at,
    lead.outreach_at,
    lead.outreach_status,
    lead.email_status,
    lead.draftstatus,
    lead.DraftStatus,
    lead.pipeline_stage,
    lead.stage
  ];

  if (rawFields.some((value) => clean(value) !== '')) {
    return true;
  }

  if (typeof lead.contacted === 'boolean') {
    return lead.contacted;
  }

  if (typeof lead.is_contacted === 'boolean') {
    return lead.is_contacted;
  }

  return isTruthyish(lead.contacted) || isTruthyish(lead.is_contacted);
}

function pushLead(lead, output) {
  if (!lead || typeof lead !== 'object') return;

  const leadId = firstNonEmpty(lead.id, lead.leadid, lead.lead_id, lead.ID);
  const website = firstNonEmpty(lead.website, lead.Website);
  const email = firstNonEmpty(lead.email, lead.Email);
  const companyNameRaw = firstNonEmpty(lead.company, lead.Company);
  const nameRaw = firstNonEmpty(lead.name, lead.Name);
  const companyName = companyNameRaw || nameRaw;
  const contactName = looksLikePersonName(nameRaw) ? nameRaw : '';
  const phone = firstNonEmpty(lead.phonenumber, lead.phone, lead.Phone, lead.telephone, lead.mobile);
  const city = firstNonEmpty(lead.city, lead.City, lead.town, lead.municipality);
  const country = firstNonEmpty(lead.country, lead.Country);
  const industry = extractIndustry(lead);
  const source = firstNonEmpty(lead.source_name, lead.source, lead.Source);
  const assigned = firstNonEmpty(lead.assigned_name, lead.assigned, lead.Assigned);
  const statusId = clean(lead.status);
  const statusText = firstNonEmpty(lead.status_name, lead.lead_status_name, lead.leadstatus, lead.lead_status, statusId);
  const statusKey = lower(`${statusId} ${statusText}`);

  const hasLeadId = leadId !== '';
  const hasWebsite = website !== '';
  const hasEmail = email !== '';
  const hasIdentity = companyName !== '' || nameRaw !== '';
  const isDeadStatus = DEAD_STATUS_IDS.has(statusId) || DEAD_STATUS_KEYWORDS.some((keyword) => statusKey.includes(keyword));
  const isLikelyContacted = CONTACTED_STATUS_KEYWORDS.some((keyword) => statusKey.includes(keyword)) || hasContactEvidence(lead);
  const statusAllowsOutreach = READY_STATUS_IDS.size === 0 || READY_STATUS_IDS.has(statusId) || statusId === '';

  let excludeReason = '';
  if (!hasLeadId) {
    excludeReason = 'missing-lead-id';
  } else if (!hasWebsite) {
    excludeReason = 'missing-website';
  } else if (!hasEmail) {
    excludeReason = 'missing-email';
  } else if (!hasIdentity) {
    excludeReason = 'missing-name-and-company';
  } else if (isDeadStatus) {
    excludeReason = `dead-status:${statusId || statusText || 'unknown'}`;
  } else if (isLikelyContacted) {
    excludeReason = 'already-contacted-or-progressed';
  } else if (!statusAllowsOutreach) {
    excludeReason = `status-not-ready:${statusId || statusText || 'unknown'}`;
  }

  output.push({
    json: {
      LeadId: String(leadId),
      CompanyName: companyName,
      ContactName: contactName,
      Email: email,
      Website: website,
      Phone: phone,
      City: city,
      Country: country,
      Industry: industry,
      Source: source,
      Assigned: assigned,
      LeadStatus: statusText || statusId,
      isCandidate: excludeReason === '',
      excludeReason,
      _rawStatusId: statusId,
      _statusAllowsOutreach: statusAllowsOutreach,
      _hasWebsite: hasWebsite,
      _hasEmail: hasEmail,
      _hasIdentity: hasIdentity,
      _isDeadStatus: isDeadStatus,
      _isLikelyContacted: isLikelyContacted
    }
  });
}

const output = [];

for (const item of items) {
  const payload = item.json?.data ?? item.json ?? [];
  if (Array.isArray(payload)) {
    for (const lead of payload) {
      pushLead(lead, output);
    }
    continue;
  }

  pushLead(payload, output);
}

return output;

const rows = $input.all().map((item) => item.json || {});
const skippedByReason = {};

for (const row of rows) {
  if (row.isCandidate) continue;
  const key = row.excludeReason || 'unknown';
  skippedByReason[key] = (skippedByReason[key] || 0) + 1;
}

return [{
  json: {
    workflow: '[STEP 6] Perfex -> Outreach Candidate Selector',
    generatedAt: new Date().toISOString(),
    totalPerfexLeads: rows.length,
    candidateCount: rows.filter((row) => row.isCandidate).length,
    skippedCount: rows.filter((row) => !row.isCandidate).length,
    skippedByReason
  }
}];

const generatedAt = new Date().toISOString();

const AGENCY_KEYWORDS = ['agency', 'byra', 'seo', 'marketing', 'digital', 'media', 'web', 'design', 'kommunikation'];
const ECOMMERCE_KEYWORDS = ['shop', 'store', 'ehandel', 'e-handel', 'ecommerce', 'e-commerce', 'butik'];
const SAAS_KEYWORDS = ['software', 'saas', 'system', 'tech', 'app', 'platform', 'cloud'];
const LOCAL_SERVICE_KEYWORDS = ['bygg', 'elektriker', 'vvs', 'stadning', 'flytt', 'klinik', 'maleri', 'snick', 'plumber', 'electric', 'clean', 'roof', 'las'];
const SWEDISH_CITY_HINTS = new Set([
  'stockholm',
  'goteborg',
  'gothenburg',
  'malmo',
  'uppsala',
  'vasteras',
  'orebro',
  'linkoping',
  'helsingborg',
  'jonkoping',
  'norrkoping',
  'lund',
  'umea',
  'gavle',
  'boras',
  'sodertalje',
  'karlstad',
  'vaxjo',
  'halmstad',
  'sundsvall'
]);

function clean(value) {
  return (value ?? '').toString().trim();
}

function lower(value) {
  return clean(value).toLowerCase();
}

function getHost(website) {
  const normalized = clean(website);
  if (!normalized) return '';
  try {
    const url = /^https?:\/\//i.test(normalized) ? normalized : `https://${normalized}`;
    return new URL(url).hostname.replace(/^www\./i, '').toLowerCase();
  } catch (error) {
    return normalized.toLowerCase().replace(/^https?:\/\//i, '').replace(/^www\./i, '').split('/')[0];
  }
}

function includesAny(haystack, keywords) {
  return keywords.some((keyword) => haystack.includes(keyword));
}

function inferTemplateType(row, host) {
  const haystack = [row.CompanyName, row.ContactName, row.Industry, host, row.Website].map(lower).join(' ');

  if (includesAny(haystack, ECOMMERCE_KEYWORDS)) return 'ecommerce';
  if (includesAny(haystack, AGENCY_KEYWORDS)) return 'agency';
  if (includesAny(haystack, SAAS_KEYWORDS)) return 'saas';
  if (includesAny(haystack, LOCAL_SERVICE_KEYWORDS)) return 'local_service';
  if (haystack.trim()) return 'company';
  return 'fallback';
}

function isLocalSwedishLead(row, host) {
  const city = lower(row.City);
  const country = lower(row.Country);

  if (city && SWEDISH_CITY_HINTS.has(city)) return true;
  if (country === 'se' || country.includes('sweden') || country.includes('sverige')) return !!city || host.endsWith('.se');
  if (host.endsWith('.se') && city) return true;
  return false;
}

function inferWorkMode(row, templateType, host) {
  if (templateType === 'agency' || templateType === 'saas') return 'remote';
  if (templateType === 'local_service') return 'local_onsite';
  if (isLocalSwedishLead(row, host)) return 'local_onsite';
  return 'hybrid';
}

function buildCandidateReason(row, templateType, workMode) {
  if (templateType === 'agency') {
    return 'Agency-like company with strong fit for SEO/web/automation profile';
  }
  if (templateType === 'saas') {
    return 'Digital or software-oriented company with website and contact email';
  }
  if (templateType === 'local_service') {
    return 'Local service company with website and contact email';
  }
  if (workMode === 'local_onsite') {
    return 'Local company with website and contact email';
  }
  return 'Has website and email, suitable for outreach';
}

function buildPersonalizationHint(row, templateType, workMode) {
  if (workMode === 'local_onsite' && clean(row.City)) {
    return `Local company in ${clean(row.City)} with website and email`;
  }
  if (templateType === 'agency') {
    return 'Likely agency or digital company';
  }
  if (templateType === 'local_service') {
    return 'Service business with digital improvement potential';
  }
  if (templateType === 'saas') {
    return 'Software-oriented company with digital product or platform angle';
  }
  if (templateType === 'ecommerce') {
    return 'Online-first company with ecommerce conversion potential';
  }
  return 'Company with website and reachable contact email';
}

return items.map((item) => {
  const row = item.json || {};
  const host = getHost(row.Website);
  const templateType = inferTemplateType(row, host);
  const workModeHint = inferWorkMode(row, templateType, host);
  const candidateReason = buildCandidateReason(row, templateType, workModeHint);
  const personalizationHint = buildPersonalizationHint(row, templateType, workModeHint);

  return {
    json: {
      LeadId: clean(row.LeadId),
      CompanyName: clean(row.CompanyName),
      ContactName: clean(row.ContactName),
      Email: clean(row.Email),
      Website: clean(row.Website),
      Phone: clean(row.Phone),
      City: clean(row.City),
      Country: clean(row.Country),
      Industry: clean(row.Industry),
      Source: clean(row.Source),
      Assigned: clean(row.Assigned),
      LeadStatus: clean(row.LeadStatus),
      CandidateReason: candidateReason,
      WorkModeHint: workModeHint,
      TemplateType: templateType,
      PersonalizationHint: personalizationHint,
      GeneratedAt: generatedAt,
      DraftStatus: 'Pending'
    }
  };
});
